/**
 * Asset helper for CRA deployed to GitHub Pages.
 * process.env.PUBLIC_URL is inlined by webpack at build time, e.g.
 * "https://Slimsh8dy.github.io/eduresources" — no trailing slash.
 */
const asset = (p) => {
  const base = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
  const path = String(p).replace(/^\//, "");
  return `${base}/${path}`;
};

/* ---- AI / Llama 3 via Groq ---- */
const AI_KEY_STORAGE = 'eduresources_groq_key';
const ApiKeyContext = React.createContext({ apiKey: '', setApiKey: () => {} });

async function callLlama(apiKey, userMsg, systemMsg = '') {
  const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model: 'llama-3.1-8b-instant',
      messages: [
        ...(systemMsg ? [{ role: 'system', content: systemMsg }] : []),
        { role: 'user', content: userMsg },
      ],
      max_tokens: 1200,
    }),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error?.message || `API error ${res.status}`);
  }
  const data = await res.json();
  return data.choices[0].message.content;
}

