function normalize(s) {
  return (s || "").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g, "");
}

/* ---- Search panel ---- */
function HeaderSearchPanel({ open, onClose }) {
  const { apiKey } = React.useContext(ApiKeyContext);
  const [mode, setMode] = React.useState('browse'); // 'browse' | 'ai'
  const [q, setQ] = React.useState("");
  const [showSuggestions, setShowSuggestions] = React.useState(false);
  // AI chat state
  const [aiQ, setAiQ] = React.useState('');
  const [aiReply, setAiReply] = React.useState('');
  const [aiLoading, setAiLoading] = React.useState(false);
  const [aiError, setAiError] = React.useState('');

  const query = normalize(q);
  const panelRef = React.useRef(null);

  const fuse = React.useMemo(() => new Fuse(ALL_RESOURCES, {
    keys: ['title', 'section'],
    threshold: 0.35,
  }), []);

  const results = React.useMemo(() => {
    if (!query) return [];
    return fuse.search(query).map(r => r.item);
  }, [query, fuse]);

  const suggestions = React.useMemo(() => {
    if (!query) return [];
    return fuse.search(query).slice(0, 5).map(r => r.item.title);
  }, [query, fuse]);

  React.useEffect(() => {
    if (!open) { setQ(""); setAiQ(""); setAiReply(""); setAiError(""); }
    function onKey(e) { if (e.key === "Escape") onClose?.(); }
    if (open) window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  React.useEffect(() => {
    function onDocClick(e) {
      if (!open) return;
      if (panelRef.current && !panelRef.current.contains(e.target)) onClose?.();
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [open, onClose]);

  const handleAskAI = async (e) => {
    e.preventDefault();
    if (!aiQ.trim() || aiLoading) return;
    setAiLoading(true); setAiReply(''); setAiError('');
    try {
      const reply = await callLlama(apiKey, aiQ.trim(), SITE_SYSTEM_PROMPT);
      setAiReply(reply);
    } catch (err) {
      setAiError(err.message);
    } finally {
      setAiLoading(false);
    }
  };

  const btnBase = { borderRadius: 999, padding: '6px 16px', fontSize: 12, fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit', transition: 'all 0.15s' };

  return (
    <div
      ref={panelRef}
      style={{
        transition: "max-height 220ms ease",
        maxHeight: open ? "80vh" : 0,
        overflowY: open ? "auto" : "hidden",
        borderBottom: open ? "1px solid var(--border-color)" : "1px solid transparent",
        backgroundColor: "var(--bg-color)",
        boxShadow: open ? "var(--shadow-md)" : "none",
      }}
      aria-hidden={!open}
    >
      <div className="container" style={{ paddingTop: 14, paddingBottom: 18 }}>

        {/* Mode tabs */}
        <div style={{ display: 'flex', gap: 6, marginBottom: 14, alignItems: 'center' }}>
          <button onClick={() => setMode('browse')} style={{ ...btnBase, background: mode === 'browse' ? 'var(--accent)' : 'transparent', color: mode === 'browse' ? 'var(--text-on-accent)' : 'var(--text-muted)', border: mode === 'browse' ? 'none' : '1px solid var(--border-color)' }}>Browse</button>
          <button onClick={() => setMode('ai')} style={{ ...btnBase, background: mode === 'ai' ? '#4f46e5' : 'transparent', color: mode === 'ai' ? '#fff' : 'var(--text-muted)', border: mode === 'ai' ? 'none' : '1px solid var(--border-color)' }}>
            ✦ Ask AI {!apiKey && <span style={{ fontSize: 10, opacity: 0.7 }}>(key needed)</span>}
          </button>
          <div style={{ flex: 1 }} />
          <button type="button" onClick={onClose} style={{ border: "1px solid var(--border-color)", background: "transparent", borderRadius: 8, padding: "6px 12px", cursor: "pointer", color: "var(--text-color)", fontSize: "0.8rem", fontWeight: 600, fontFamily: "inherit" }}>Close</button>
        </div>

        {/* Browse mode */}
        {mode === 'browse' && (
          <>
            <div style={{ position: 'relative', marginBottom: 12 }}>
              <input
                autoFocus={open && mode === 'browse'}
                aria-label="Search resources"
                placeholder="Search — try 'utilitarianism', 'Kant', 'mind map'…"
                value={q}
                onChange={(e) => { setQ(e.target.value); setShowSuggestions(true); }}
                onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
                style={{ width: '100%', boxSizing: 'border-box', padding: "10px 14px", borderRadius: 8, border: "1px solid var(--border-color)", fontSize: 15, backgroundColor: "var(--bg-input)", color: "var(--text-color)", fontFamily: "inherit", outline: "none" }}
              />
              {showSuggestions && suggestions.length > 0 && (
                <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, backgroundColor: "var(--bg-card)", border: "1px solid var(--border-color)", borderRadius: 8, zIndex: 20, boxShadow: "var(--shadow-md)", marginTop: 4 }}>
                  {suggestions.map((sug, i) => (
                    <div key={i} onMouseDown={() => { setQ(sug); setShowSuggestions(false); }}
                      style={{ padding: '9px 14px', cursor: 'pointer', fontSize: '0.875rem', color: "var(--text-color)", borderBottom: i < suggestions.length - 1 ? "1px solid var(--border-color)" : "none" }}
                      onMouseEnter={e => e.target.style.backgroundColor = "var(--border-color)"}
                      onMouseLeave={e => e.target.style.backgroundColor = ""}
                    >{sug}</div>
                  ))}
                </div>
              )}
            </div>
            {query ? (
              <>
                <p style={{ margin: "0 0 14px", fontSize: "0.875rem", color: "var(--text-muted)" }}>
                  {results.length} result{results.length === 1 ? "" : "s"} for "<strong style={{ color: "var(--text-color)" }}>{q}</strong>"
                </p>
                <div className="card-grid">
                  {results.map((r) => {
                    if (r.type === "audio") return <AudioCard key={`${r.type}:${r.file}`} title={r.title} file={r.file} desc={r.section} />;
                    if (r.type === "link") return <ExternalLinkCard key={`${r.type}:${r.url}`} title={r.title} url={r.url} desc={r.section} cta="Open Podcast" />;
                    return <DownloadCard key={`${r.type}:${r.file}`} title={r.title} file={r.file} desc={r.section} />;
                  })}
                </div>
              </>
            ) : (
              <p style={{ color: "var(--text-muted)", margin: 0, fontSize: "0.875rem" }}>
                Try: <em>utilitarianism</em>, <em>Kant</em>, <em>Augustine</em>, <em>mind map</em>
              </p>
            )}
          </>
        )}

        {/* AI mode */}
        {mode === 'ai' && (
          <div>
            {!apiKey ? (
              <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: 10, padding: '16px 18px', fontSize: 13, color: 'var(--text-muted)', lineHeight: 1.6 }}>
                ✦ AI search requires a free Groq API key (Llama 3). Click <strong>API Key</strong> in the nav to add yours — free at console.groq.com, stored only in your browser.
              </div>
            ) : (
              <form onSubmit={handleAskAI}>
                <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
                  <input
                    autoFocus={open && mode === 'ai'}
                    value={aiQ}
                    onChange={e => setAiQ(e.target.value)}
                    placeholder="Ask anything — e.g. 'Where can I find Kant notes?' or 'How do I write a philosophy essay?'"
                    style={{ flex: 1, padding: "10px 14px", borderRadius: 8, border: "1px solid var(--border-color)", fontSize: 14, backgroundColor: "var(--bg-input)", color: "var(--text-color)", fontFamily: "inherit", outline: "none" }}
                  />
                  <button type="submit" disabled={!aiQ.trim() || aiLoading}
                    style={{ background: '#4f46e5', color: '#fff', border: 'none', borderRadius: 8, padding: '10px 18px', fontWeight: 700, fontSize: 13, cursor: aiQ.trim() && !aiLoading ? 'pointer' : 'not-allowed', opacity: aiQ.trim() && !aiLoading ? 1 : 0.5, fontFamily: 'inherit', whiteSpace: 'nowrap' }}>
                    {aiLoading ? '...' : 'Ask'}
                  </button>
                </div>
                {aiError && <div style={{ background: '#fff1f2', border: '1px solid #fca5a5', borderRadius: 8, padding: '10px 14px', fontSize: 13, color: '#dc2626', marginBottom: 10 }}>{aiError}</div>}
                {aiReply && (
                  <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: 10, padding: '14px 16px', fontSize: 14, color: 'var(--text-color)', lineHeight: 1.75, whiteSpace: 'pre-wrap' }}>
                    <span style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: '#4f46e5', display: 'block', marginBottom: 8 }}>✦ AI Response</span>
                    {aiReply}
                  </div>
                )}
                {!aiReply && !aiLoading && (
                  <p style={{ color: 'var(--text-muted)', fontSize: 13, margin: 0 }}>Ask about resources, topics, or where to find specific materials on the site.</p>
                )}
              </form>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

