function exportToPDF(data, question) {
  const sections = [...new Set(SCAFFOLD_STEPS.map(s => s.section))];
  const body = sections.map(sec => {
    const steps = SCAFFOLD_STEPS.filter(s => s.section === sec);
    return `
      <div class="section">
        <div class="sec-title">${sec}</div>
        ${steps.map(s => `
          <div class="field">
            <div class="field-label">${s.label}</div>
            <div class="field-value">${(data[s.id] || "").replace(/\n/g, "<br>") || '<span class="empty">—</span>'}</div>
          </div>
        `).join("")}
      </div>`;
  }).join("");

  const html = `<!DOCTYPE html><html><head><meta charset="utf-8">
    <title>Essay Plan${question ? " — " + question.slice(0, 60) : ""}</title>
    <style>
      body{font-family:Georgia,serif;max-width:680px;margin:0 auto;padding:32px 24px;color:#1a1a1a;font-size:13px}
      h1{font-size:18px;margin:0 0 4px;color:#0f172a}
      .q{font-size:12px;color:#475569;margin:0 0 28px;font-style:italic}
      .section{margin-bottom:24px;page-break-inside:avoid}
      .sec-title{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:#94a3b8;border-bottom:1px solid #e2e8f0;padding-bottom:4px;margin-bottom:10px}
      .field{margin-bottom:12px}
      .field-label{font-size:11px;font-weight:700;color:#374151;margin-bottom:3px}
      .field-value{font-size:13px;line-height:1.7;color:#111;background:#f8f9fa;padding:8px 12px;border-left:3px solid #d1d5db}
      .empty{color:#9ca3af;font-style:italic}
      @media print{body{padding:0}}
    </style></head><body>
    <h1>Philosophy Essay Plan</h1>
    ${question ? `<p class="q">${question}</p>` : ""}
    ${body}
    </body></html>`;

  const win = window.open("", "_blank");
  if (!win) { alert("Allow pop-ups to export as PDF."); return; }
  win.document.write(html);
  win.document.close();
  setTimeout(() => win.print(), 350);
}

function EssayScaffold() {
  const [step, setStep] = React.useState(0);
  const [data, setData] = React.useState({});
  const [error, setError] = React.useState(false);
  const [done, setDone] = React.useState(false);
  const textareaRef = React.useRef(null);

  const current = SCAFFOLD_STEPS[step];
  const total   = SCAFFOLD_STEPS.length;
  const c       = SC[current?.col] || SC.setup;
  const pct     = Math.round((step / total) * 100);

  // Focus textarea when step changes
  React.useEffect(() => {
    if (textareaRef.current) textareaRef.current.focus();
  }, [step]);

  const handleNext = () => {
    if (!data[current.id]?.trim()) { setError(true); return; }
    setError(false);
    if (step < total - 1) setStep(s => s + 1);
    else setDone(true);
  };

  const handleBack = () => { setError(false); setStep(s => Math.max(0, s - 1)); };

  const handleReset = () => {
    if (!window.confirm("Reset the essay plan? All entries will be lost.")) return;
    setStep(0); setData({}); setError(false); setDone(false);
  };

  const s = { fontFamily: "'Inter',system-ui,sans-serif" };

  // ── Done screen
  if (done) {
    return (
      <div style={{ ...s, maxWidth: 640, margin: "0 auto", padding: "24px 0 40px" }}>
        <div style={{ background: "#f0fdf4", border: "1.5px solid #86efac", borderRadius: 12, padding: "28px 24px", textAlign: "center", marginBottom: 20 }}>
          <div style={{ fontSize: 32, marginBottom: 8 }}>✓</div>
          <h2 style={{ margin: "0 0 6px", color: "#14532d", fontSize: 18 }}>Essay plan complete!</h2>
          <p style={{ margin: "0 0 20px", color: "#166534", fontSize: 13 }}>All {total} steps filled in. You can export your plan as a PDF or start a new one.</p>
          <div style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap" }}>
            <button onClick={() => exportToPDF(data, data.essay_q)} style={{ background: "#15803d", color: "#fff", border: "none", borderRadius: 8, padding: "10px 20px", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>
              Export as PDF
            </button>
            <button onClick={handleReset} style={{ background: "#fff", color: "#374151", border: "1.5px solid #d1d5db", borderRadius: 8, padding: "10px 20px", fontWeight: 600, fontSize: 14, cursor: "pointer" }}>
              Start New Plan
            </button>
          </div>
        </div>

        {/* Summary */}
        {[...new Set(SCAFFOLD_STEPS.map(s => s.section))].map(sec => (
          <div key={sec} style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: "#94a3b8", marginBottom: 6 }}>{sec}</div>
            {SCAFFOLD_STEPS.filter(s => s.section === sec).map(st => (
              <div key={st.id} style={{ marginBottom: 8, background: "#fff", border: "1px solid #e2e8f0", borderRadius: 8, padding: "10px 14px" }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: "#374151", marginBottom: 3 }}>{st.label}</div>
                <div style={{ fontSize: 13, color: "#1a1a1a", lineHeight: 1.6, whiteSpace: "pre-wrap" }}>{data[st.id] || <span style={{ color: "#9ca3af", fontStyle: "italic" }}>—</span>}</div>
              </div>
            ))}
          </div>
        ))}
      </div>
    );
  }

  // ── Step screen
  return (
    <div style={{ ...s, maxWidth: 640, margin: "0 auto", padding: "20px 0 40px" }}>

      {/* Top bar: progress + reset */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
        <div style={{ flex: 1 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#94a3b8", marginBottom: 4 }}>
            <span>Step {step + 1} of {total}</span>
            <span>{pct}% complete</span>
          </div>
          <div style={{ height: 5, background: "#e2e8f0", borderRadius: 99, overflow: "hidden" }}>
            <div style={{ height: "100%", width: `${pct}%`, background: c.bar, borderRadius: 99, transition: "width 0.3s ease" }} />
          </div>
        </div>
        <button onClick={handleReset} title="Reset plan" style={{ background: "transparent", border: "1px solid #e2e8f0", borderRadius: 7, padding: "5px 10px", fontSize: 11, color: "#6b7280", cursor: "pointer", whiteSpace: "nowrap" }}>
          Reset
        </button>
      </div>

      {/* Essay question banner (shown from step 1 onward) */}
      {step > 0 && data.essay_q && (
        <div style={{ background: "#f1f5f9", border: "1px solid #e2e8f0", borderRadius: 8, padding: "8px 14px", marginBottom: 14, fontSize: 12, color: "#475569" }}>
          <strong style={{ color: "#1e293b" }}>Essay question:</strong> {data.essay_q}
        </div>
      )}

      {/* Step card */}
      <div style={{ background: "#fff", border: `1.5px solid ${c.bar}40`, borderRadius: 12, overflow: "hidden", boxShadow: "0 2px 12px rgba(0,0,0,0.06)" }}>
        {/* Card header */}
        <div style={{ background: c.bg, borderBottom: `1.5px solid ${c.bar}30`, padding: "14px 18px" }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.1em", color: c.bar, marginBottom: 4 }}>
            {current.section}
          </div>
          <div style={{ fontSize: 17, fontWeight: 700, color: "#0f172a" }}>{current.label}</div>
        </div>

        {/* Card body */}
        <div style={{ padding: "18px 18px 14px" }}>
          <p style={{ margin: "0 0 6px", fontSize: 13, color: "#374151", fontWeight: 500, lineHeight: 1.5 }}>{current.prompt}</p>
          <p style={{ margin: "0 0 12px", fontSize: 11, color: "#94a3b8", fontStyle: "italic", lineHeight: 1.5 }}>{current.hint}</p>

          <textarea
            ref={textareaRef}
            value={data[current.id] || ""}
            onChange={e => { setData(d => ({ ...d, [current.id]: e.target.value })); setError(false); }}
            onKeyDown={e => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) handleNext(); }}
            rows={5}
            placeholder="Write your answer here…"
            style={{
              width: "100%", boxSizing: "border-box",
              padding: "10px 12px", fontSize: 13, lineHeight: 1.65,
              border: error ? "1.5px solid #f87171" : "1.5px solid #e2e8f0",
              borderRadius: 8, resize: "vertical", fontFamily: "inherit",
              color: "#1a1a1a", background: error ? "#fff5f5" : "#fafafa",
              outline: "none",
            }}
          />
          {error && (
            <p style={{ margin: "5px 0 0", fontSize: 12, color: "#dc2626" }}>
              Please fill in this field before continuing.
            </p>
          )}
        </div>

        {/* Navigation */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 18px 16px", borderTop: "1px solid #f1f5f9" }}>
          <button
            onClick={handleBack}
            disabled={step === 0}
            style={{ background: "transparent", border: "1px solid #e2e8f0", borderRadius: 8, padding: "9px 18px", fontSize: 13, fontWeight: 600, color: step === 0 ? "#cbd5e1" : "#374151", cursor: step === 0 ? "default" : "pointer" }}
          >
            ← Back
          </button>
          <span style={{ fontSize: 11, color: "#cbd5e1" }}>Cmd+Enter to advance</span>
          <button
            onClick={handleNext}
            style={{ background: c.bar, color: "#fff", border: "none", borderRadius: 8, padding: "9px 20px", fontSize: 13, fontWeight: 700, cursor: "pointer" }}
          >
            {step === total - 1 ? "Complete Plan" : "Next →"}
          </button>
        </div>
      </div>

      {/* Step map */}
      <div style={{ marginTop: 18, display: "flex", flexWrap: "wrap", gap: 4 }}>
        {SCAFFOLD_STEPS.map((st, i) => (
          <div
            key={st.id}
            title={`${st.section} — ${st.label}`}
            style={{
              width: 10, height: 10, borderRadius: 2,
              background: i < step ? SC[st.col].bar : i === step ? SC[st.col].bar : "#e2e8f0",
              opacity: i < step ? 1 : i === step ? 1 : 0.4,
              border: i === step ? `2px solid ${SC[st.col].bar}` : "2px solid transparent",
              boxSizing: "border-box",
            }}
          />
        ))}
      </div>
    </div>
  );
}

